1	<!doctype html><html><head><meta charset="utf-8">
2	<title>Float backdrop triage</title>
3	<style>
4	  :root { color-scheme: dark; }
5	  body { background:#101014; color:#ddd; margin:0 0 130px 0;
6	         font:14px/1.4 -apple-system, system-ui, sans-serif; }
7	  header { position:sticky; top:0; background:#101014e6; backdrop-filter:blur(6px);
8	           padding:12px 20px; z-index:2; border-bottom:1px solid #26262e; }
9	  h1 { font-size:17px; margin:0; } h1 small { color:#888; font-weight:400; }
10	  h2 { margin:26px 20px 10px; font-size:15px; color:#bbb; } h2 .n { color:#666; }
11	  .grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(300px,1fr));
12	          gap:12px; padding:0 20px; }
13	  .card { position:relative; margin:0; cursor:pointer; border-radius:8px;
14	          overflow:hidden; background:#17171c; outline:2px solid transparent; }
15	  .card img { width:100%; aspect-ratio:2/1; object-fit:cover; display:block; }
16	  .card img.orig { aspect-ratio:auto; max-height:170px; object-fit:contain;
17	                   background:#000; border-top:1px solid #26262e; }
18	  .card .lbl { font-size:10px; letter-spacing:.08em; text-transform:uppercase;
19	               color:#777; padding:3px 9px 2px; background:#131318; }
20	  .card figcaption { padding:6px 9px 8px; color:#aaa; }
21	  .card figcaption b { color:#ddd; font-weight:600; }
22	  .card .tag { position:absolute; top:8px; right:8px; background:#d33;
23	               color:#fff; font-weight:700; font-size:12px; padding:2px 8px;
24	               border-radius:4px; display:none; }
25	  .card.removed { outline-color:#d33; }
26	  .card.removed img { filter:grayscale(.9) brightness(.45); }
27	  .card.removed .tag { display:block; }
28	  footer { position:fixed; bottom:0; left:0; right:0; background:#17171cf2;
29	           border-top:1px solid #26262e; padding:10px 20px;
30	           display:flex; gap:14px; align-items:center; }
31	  footer textarea { flex:1; height:64px; background:#101014; color:#e88;
32	                    border:1px solid #333; border-radius:6px; padding:6px 8px;
33	                    font:12px ui-monospace, monospace; resize:none; }
34	  footer button { background:#2a2a33; color:#ddd; border:1px solid #444;
35	                  border-radius:6px; padding:8px 14px; cursor:pointer; }
36	  footer button:hover { background:#34343e; }
37	  #count { min-width:110px; color:#e88; font-weight:600; }
38	</style></head><body>
