import Foundation
import RealityKit
import simd

/// The test planet/moon bodies built by `scripts/render_planets.py`, mounted as REAL GEOMETRY.
///
/// Why geometry and not another painted sky: the backdrop HEICs sit at one near-infinite depth
/// (depth_floor 0.94, ~0.2% baseline), so anything composited into the equirect has no parallax
/// between the eyes — which is most of why the old `saturn1` sky reads as a picture of space
/// rather than a place. A body the viewer is meant to feel *near* has to be actual geometry with
/// real stereo. That is this layer's whole reason to exist.
///
/// This is the on-device triage surface for those bakes — pick a body, judge scale, sharpness,
/// and (for Saturn) whether the baked ring shadow reads. It is not the shipping §7c planet layer.
@MainActor
enum PlanetBodies {

    struct Body: Identifiable, Hashable {
        /// Basename of both `<name>.usdz` (bundle) and `<name>.jpg` (Previews/).
        let name: String
        let title: String
        /// One-line note for the picker — what this card is actually asking you to judge.
        let note: String
        /// On-screen angular DIAMETER of the whole silhouette at `distance`, in degrees. Sized
        /// for hero framing, roughly matching the ~55%-of-frame previews `render_preview`
        /// produces, so the device view and the contact sheet are comparable.
        let angularDiameter: Float
        /// True when the USDZ carries its lighting baked into `emissiveColor` — the Saturn bake
        /// deliberately routes the baked map to Emission so the surface is unlit and "what you
        /// baked is exactly what shows" (render_planets.py stage 2). Those bodies must NOT get
        /// the sun light: a live light would lay a second, contradictory terminator over the
        /// baked one.
        let unlit: Bool

        var id: String { name }
    }

    /// Saturn's two cards sit adjacent on purpose — the bake is the thing under test, and the
    /// unbaked build is the control you compare it against.
    static let catalog: [Body] = [
        Body(name: "saturn_baked", title: "Saturn (baked)",
             note: "Ring shadow ray-traced into the colour map; unlit.",
             angularDiameter: 50, unlit: true),
        Body(name: "saturn", title: "Saturn (live light)",
             note: "Control for the bake — no ring shadow on the globe.",
             angularDiameter: 50, unlit: false),
        Body(name: "jupiter", title: "Jupiter",
             note: "Cassini + Juno 14400px. GRS turned to face you.",
             angularDiameter: 44, unlit: false),
        Body(name: "venus", title: "Venus",
             note: "Retrograde 177° tilt — \"north\" is meant to look upside down.",
             angularDiameter: 34, unlit: false),
        Body(name: "iapetus", title: "Iapetus",
             note: "Dark Cassini Regio lit flat, so it reads as terrain not shadow.",
             angularDiameter: 30, unlit: false),
    ]

    /// Metres in front of the viewer. Comfortably outside the §7d/§9 safety bubble (~2–3 m) and
    /// far inside the sky sphere (radius 1000), so the body sits unambiguously in front of the
    /// backdrop with real stereo separation from it. Distance and `angularDiameter` only ever
    /// appear together as a ratio, so this number sets *stereo strength*, not apparent size:
    /// nearer would give more parallax but starts to crowd the bubble.
    static let distance: Float = 60

    static let rootName = "PlanetRoot"
    private static let bodyName = "PlanetBody"
    private static let sunName  = "PlanetSun"

    /// Empty container, mounted once. Lives under `sceneRoot` (not `sceneContainer`) so it
    /// inherits the recenter yaw for free and a sky swap leaves it alone —
    /// `SpatialImageEnvironment.attach` only removes children named `ImportedSpatial_Skybox`.
    static func makeRoot() -> Entity {
        let e = Entity()
        e.name = rootName
        return e
    }

    /// Swap the shown body. `nil` clears the layer (back to sky only).
    ///
    /// Returns false only if the chosen body could not be loaded — the caller uses that to keep
    /// the selection honest rather than showing a checkmark against an empty sky.
    @discardableResult
    static func show(_ body: Body?, in root: Entity) async -> Bool {
        root.children.forEach { $0.removeFromParent() }
        guard let body else { return true }

        guard let url = Bundle.main.url(forResource: body.name, withExtension: "usdz",
                                        subdirectory: "Models")
            ?? Bundle.main.url(forResource: body.name, withExtension: "usdz")
        else {
            print("[Float] PlanetBodies: '\(body.name).usdz' is not in the bundle")
            return false
        }

        let entity: Entity
        do {
            entity = try await Entity(contentsOf: url)
        } catch {
            print("[Float] PlanetBodies: '\(body.name).usdz' failed to load (\(error))")
            return false
        }

        // Size from the entity's MEASURED bounds rather than from the authored radius. The
        // exporter's unit sphere is radius 1, but USD carries a metersPerUnit and Saturn's
        // silhouette is the ring annulus (RING_OUTER = 2.27 globe radii), not the globe — so
        // "what does this subtend" is a question only the real bounds can answer, and asking
        // them keeps rings and bare globes on one code path.
        let bounds = entity.visualBounds(relativeTo: nil)
        let radius = bounds.boundingRadius
        guard radius > 0, radius.isFinite else {
            print("[Float] PlanetBodies: '\(body.name)' has degenerate bounds")
            return false
        }
        let target = distance * tan(body.angularDiameter * 0.5 * .pi / 180)
        entity.scale *= target / radius
        // Re-centre on the measured centroid so an off-origin export still lands dead ahead.
        entity.position = -bounds.center * (target / radius)

        let holder = Entity()
        holder.name = bodyName
        holder.addChild(entity)
        // Straight ahead, at roughly eye height — the immersive space's origin is on the floor
        // under the wearer, and at 60 m this 1.5 m lift is ~1.4°, i.e. cosmetic. It costs
        // nothing and keeps the body centred rather than fractionally low.
        holder.position = [0, 1.5, -distance]
        root.addChild(holder)

        if !body.unlit { root.addChild(makeSun(target: holder.position)) }
        return true
    }

    /// Directional key light for the unbaked bodies. There is no IBL in a full immersive space,
    /// so without this a UsdPreviewSurface body renders black.
    ///
    /// Placed up and to the LEFT and slightly on the viewer's side of the body, which puts the
    /// terminator down the right-hand limb — the same handedness as the Blender previews, so a
    /// body doesn't appear to flip its lighting between the contact sheet and the headset.
    private static func makeSun(target: SIMD3<Float>) -> Entity {
        let sun = DirectionalLight()
        sun.name = sunName
        // Bright: these are albedo maps of sunlit bodies, and the surround is pure black, so an
        // interior-lighting default reads as dusk.
        sun.light.intensity = 3000
        sun.light.color = .white
        sun.shadow = nil    // one convex body, nothing to receive a shadow it doesn't already own
        // `look` aims the entity's -Z (a DirectionalLight's emission direction) at `target`.
        sun.look(at: target,
                 from: target + normalize(SIMD3<Float>(-1.0, 0.45, 0.55)) * distance,
                 relativeTo: nil)
        return sun
    }
}

